// Shared transport for both the 3D game and the knowledge graph.
let config={};try{const r=await fetch(new URL('cloud-config.json',import.meta.url),{cache:'no-store'});if(r.ok)config=await r.json();}catch{}
const cloud=typeof config.apiBase==='string'&&/^https:\/\/[a-z0-9]+\.execute-api\.[a-z0-9-]+\.amazonaws\.com\/?$/.test(config.apiBase);
const base=cloud?config.apiBase.replace(/\/$/,''):new URL('api/',document.baseURI).href.replace(/\/$/,'');
let sessionPromise=null;
const key='sansan-guest-'+base;
function saved(){try{const s=JSON.parse(sessionStorage.getItem(key));return s?.expiresAt>Date.now()/1000+60?s:null;}catch{return null;}}
async function session(){const cached=saved();if(cached)return cached;if(sessionPromise)return sessionPromise;sessionPromise=(async()=>{const r=await fetch(base+'/session',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});const s=await r.json();if(!r.ok)throw Error(s.error||'无法建立访客会话');try{sessionStorage.setItem(key,JSON.stringify(s));}catch{}return s;})();try{return await sessionPromise;}finally{sessionPromise=null;}}
async function request(path,options={}){if(!cloud)return fetch(base+path,options);if(path==='/health')return fetch(base+path,options);let s=await session();let r=await fetch(base+path,{...options,headers:{...options.headers,Authorization:'Bearer '+s.token}});if(r.status===401){try{sessionStorage.removeItem(key);}catch{}if(path!=='/chat')return r;s=await session();r=await fetch(base+path,{...options,headers:{...options.headers,Authorization:'Bearer '+s.token}});}return r;}
function delay(ms,signal){return new Promise((resolve,reject)=>{if(signal?.aborted)return reject(new DOMException('Aborted','AbortError'));const abort=()=>{clearTimeout(timer);reject(new DOMException('Aborted','AbortError'));};const timer=setTimeout(()=>{signal?.removeEventListener('abort',abort);resolve();},ms);signal?.addEventListener('abort',abort,{once:true});});}
async function perform(path,options={}){let r=await request(path,options);if(!cloud||path!=='/chat'||r.status!==202)return r;let job=await r.json();const started=Date.now();while(Date.now()-started<160000){if(job.status==='done')return Response.json({reply:job.reply,provider:'AWS AgentCore'});if(['failed','cancelled','expired'].includes(job.status))return Response.json({error:job.error||(job.status==='cancelled'?'回答已停止':'三三暂时没连上模型，请稍后重试。')},{status:503});await delay(1500,options.signal);r=await request('/jobs/'+encodeURIComponent(job.requestId),{signal:options.signal});if([429,502,503,504].includes(r.status)){await delay(2000,options.signal);continue;}if(!r.ok)return r;job=await r.json();}await request('/cancel',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({requestId:job.requestId})}).catch(()=>{});return Response.json({error:'这次思考时间较长，已请求停止，请稍后重试。'},{status:504});}

let activeRequest=null;const pendingKey=key+'-pending';
if(cloud){try{const prior=JSON.parse(sessionStorage.getItem(pendingKey));if(prior?.requestId){request('/cancel',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(prior)}).finally(()=>sessionStorage.removeItem(pendingKey)).catch(()=>{});}}catch{}}
export async function apiFetch(path,options={}){if(!cloud||path!=='/chat')return perform(path,options);const id=JSON.parse(options.body).requestId;activeRequest=id;try{sessionStorage.setItem(pendingKey,JSON.stringify({requestId:id}));}catch{}try{return await perform(path,options);}catch(e){if(e.name==='AbortError')throw e;if(e instanceof TypeError)throw Error('网络连接暂时中断，请稍后重试。');throw e;}finally{if(activeRequest===id){activeRequest=null;try{sessionStorage.removeItem(pendingKey);}catch{}}}}
addEventListener('pagehide',()=>{const s=saved();if(cloud&&activeRequest&&s)fetch(base+'/cancel',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+s.token},body:JSON.stringify({requestId:activeRequest}),keepalive:true}).catch(()=>{});});
